    CODICI_ATECO,
    TIPOLOGIA_BENEFICIARI,
    DIMENSIONE_AZIENDALE,
    CODICE_ATECO_RILEVANZA,
    DATA_INIZIO_EVENTO,
    DATA_FINE_EVENTO,
    DISABILITA_CONTROLLO_IMPORTO_AMMISSIBILE,
    DISABILITA_PROTOCOLLAZIONE_ALLEGATI_INTEGRAZIONE,
    DISABILITA_CAMPO_OGGETTO,
    ABILITA_FIRMA_DATA_ISTANZA;
}

