@Component(//
        immediate = true, //
        property = { //
                "javax.portlet.name=" + GestioneBandiFrontendPortletKeys.GESTIONEBANDIFRONTEND, //
                "mvc.command.name=" + GestioneBandiFrontendPortletKeys.DETTAGLIO_NUOVO_RENDER_COMMAND//
        }, //
        service = MVCRenderCommand.class//
) //
public class DettaglioNuovoRenderCommand implements MVCRenderCommand {

    private static final Log _log = LogFactoryUtil.getLog(DettaglioNuovoRenderCommand.class);

    @Reference private GestioneBandiMiddlewareService gestioneBandiMiddlewareService;

    @Reference private ProcessoLocalService processoLocalService;

    @Reference private BandoFormLocalService bandoFormLocalService;

    @Reference private FormLocalService formLocalService;

    @Reference private BandoLocalService bandoLocalService;

    @Reference private TipologiaBandoLocalService tipologiaBandoLocalService;

    @Reference private GroupLocalService groupLocalService;

    @Reference private RequisitoDomandaBandoLocalService requisitoDomandaBandoLocalService;

    @Reference private CriterioValutazioneLocalService criterioValutazioneLocalService;

    @Reference private ContributoBandoLocalService contributoBandoLocalService;

    @Reference private ValoreRequisitoDomandaLocalService valoreRequisitoDomandaLocalService;

    @Reference private StatoDomandaLocalService statoDomandaLocalService;

    @Reference private TermineBandoLocalService termineBandoLocalService;

    @Reference private OrganizationLocalService organizationLocalService;

    @Reference private StatoDomandaBandoLocalService statoDomandaBandoLocalService;

    @Reference private SottoOrganizzazioneLocalService sottoOrganizzazioneLocalService;

    @Reference private OperazioneLocalService operazioneLocalService;

    @Reference private DatoBandoLocalService datoBandoLocalService;

    @Reference private ValoreDatoBandoLocalService valoreDatoBandoLocalService;

    @Reference private AreaTematicaBandoLocalService areaTematicaBandoLocalService;

    @Reference private BudgetBandoLocalService budgetBandoLocalService;

    @Reference
    private AuditService auditService;

    @Reference
    private FormulaCalcoloLocalService formulaCalcoloLocalService;

    @Reference
    private RangeImportiValutazioneLocalService rangeImportiValutazioneLocalService;

    @Reference
    private TemplatePdfLocalService templatePdfLocalService;

    @Reference
    private TemplatePdfFileService templatePdfFileService;

    @Reference
    private BandoTipologiaEnteLocalService bandoTipologiaEnteLocalService;

    @Reference
    private BandoIntegrazioniDatiLocalService bandoIntegrazioniDatiLocalService;

    @Reference
    private TipologiaServizioEsternoIntegrazioniLocalService tipologiaServizioEsternoIntegrazioniLocalService;

    @Override
    public String render(RenderRequest renderRequest, RenderResponse renderResponse) throws PortletException{
        long idCodiceAteco           = 0;
        long idTipologiaBeneficiario = 0;
        long idDimensioneAziendale   = 0;

        ThemeDisplay themeDisplay = (ThemeDisplay) renderRequest.getAttribute(WebKeys.THEME_DISPLAY);

        // Long organizationId = ParamUtil.getLong(renderRequest,
        // GestioneBandiFrontendPortletKeys.ORGANIZZAZIONE_ID);
        Long organizationId = themeDisplay.getSiteGroup().getOrganizationId();
        long idBando        = ParamUtil.getLong(renderRequest, GestioneBandiFrontendPortletKeys.ID_BANDO);
        String erroreValidazioneFormule = ParamUtil.getString(renderRequest, "erroreValidazioneFormule");

        List<Servizio>               listaServizi                           = new ArrayList<Servizio>();
        List<Processo>               listaProcessi                          = new ArrayList<Processo>();
        List<Form>                   listaFormPrincipali                    = new ArrayList<Form>();
        List<Form>                   listaFormIntegrativi                   = new ArrayList<Form>();
        List<TipologiaBando>         listaTipologiaBando                    = new ArrayList<>();
        List<StatoDomanda>           listaStatoDomanda                      = new ArrayList<>();
        List<StatoDomanda>           listaStatoDomandaAutocomplete          = new ArrayList<>();
        List<ValoreRequisitoDomanda> listaValoreRequisitoDomanda            = new ArrayList<>();
        List<RequisitoDomandaBando>  listaRequisitoDomandaBando             = new ArrayList<>();
        List<RequisitoDomandaBando>  listaRequisitoDomandaBandoMod          = new ArrayList<>(listaRequisitoDomandaBando);
        List<CriterioValutazione>    listaCriterioValutazione               = new ArrayList<>();
        List<ContributoBando>        listaContributoBando                   = new ArrayList<>();
        List<TermineBando>           listaTermineBando                      = new ArrayList<>();
        List<TermineBando>           termineBandoTmpList                    = new ArrayList<TermineBando>();
        List<TermineBando>           termineBandoVariabiliTmpList           = new ArrayList<TermineBando>();
        List<StatoDomandaBando>      listaStatoDomandaBando                 = new ArrayList<>();
        List<SottoOrganizzazione>    listaSottoOrganizzazione               = new ArrayList<>();
        List<StatoDomandaBandoDTO>   listaDomandaStatoDTO                   = new ArrayList<>();
        List<String>                 listaFormIntegrativiSelected           = new ArrayList<>();
        List<String>                 listaFormIntegrativiEsecuzioneSelected = new ArrayList<>();
        List<String>                 listaFormIntegrativiAnnullamentoSelected = new ArrayList<>();
        List<Operazione>             operazioni                             = new ArrayList<>();
        List<BudgetBando>            budgetsBando                           = new ArrayList<>();
        List<RangeImportiValutazione>            rangeImportiValutazione                           = new ArrayList<>();

        Map<Long, List<ValoreRequisitoDomanda>> mapValoreRequisitoDomanda      = new HashMap<>();
        Map<Long, List<ValoreRequisitoDomanda>> mapValoreCodiceAteco           = new HashMap<>();
        Map<Long, List<ValoreRequisitoDomanda>> mapValoreTipologiaBeneficiario = new HashMap<>();
        Map<Long, List<ValoreRequisitoDomanda>> mapValoreDimensioneAziendale   = new HashMap<>();

        List<JournalArticle>      listaArticoliCatalogoBandi = new ArrayList<JournalArticle>();
        List<JournalArticle>      listaArticoliFaqBandi = new ArrayList<JournalArticle>();
        Map<String, List<Layout>> pagineDisponibili          = new HashMap<>();

        Bando  bando                           = null;
        String listaFormIntegrativiBando       = null;
        Form   formPrincipale                  = null;
        String listaFormatiFirmaDigitaleString = "";
        String listaFasiAssegnabilitaImportoString = "";
        long    siteGroupId = themeDisplay.getSiteGroupId();
        List<FormulaCalcolo> formuleCalcolo = new ArrayList<FormulaCalcolo>();

        List<TemplatePdf> listaTemplatePdfIstanza = new ArrayList<TemplatePdf>();
        List<TemplatePdf> listaTemplatePdfSoccorsoIstruttorio = new ArrayList<TemplatePdf>();
        List<TemplatePdf> listaTemplatePdfIstanzaSoccorsoIstruttorio = new ArrayList<TemplatePdf>();
        List<TemplatePdf> listaTemplatePdfIstanzaAnnullamento = new ArrayList<TemplatePdf>();
        List<TemplatePdf> listaTemplatePdfDisciplinare = new ArrayList<TemplatePdf>();
        List<TemplatePdf> listaTemplatePdfDisciplinareEsecuzione = new ArrayList<>();
        List<TemplatePdf> listaTemplatePdfPrimaDomandaAnticipo = new ArrayList<TemplatePdf>();
        List<TemplatePdf> listaTemplatePdfSecondaDomandaAnticipo = new ArrayList<TemplatePdf>();
        List<TemplatePdf> listaTemplatePdfEsitoDomanda = new ArrayList<TemplatePdf>();

        try{
            // Caricamento liste oggetti
            _log.debug("themeDisplay.getSiteGroup().getOrganizationId():" + themeDisplay.getSiteGroup()
                    .getOrganizationId());

            operazioni = operazioneLocalService.getOperaziones(-1, -1);
            List<Processo> listaProcessiOrganization = processoLocalService.getListaProcessiByAttivo(true, siteGroupId);
            List<Form> listaFormPrincipaliOrganization = formLocalService.getListaFormByOrganizationPrincipale(siteGroupId, true);
            List<Form> listaFormIntegrativiOrganization = formLocalService.getListaFormByOrganizationPrincipale(siteGroupId, false);

            Group globalGroup   = groupLocalService.getGroup(themeDisplay.getCompanyId(), GroupConstants.GUEST);
            long  globalGroupId = globalGroup.getGroupId();
            List<Processo> listaProcessiGlobal = processoLocalService.getListaProcessiByAttivo(true, globalGroupId);
            List<Form> listaFormPrincipaliGlobal = formLocalService.getListaFormByOrganizationPrincipale(globalGroupId, true);
            List<Form> listaFormIntegrativiGlobal = formLocalService.getListaFormByOrganizationPrincipale(globalGroupId, false);

            listaProcessi        = Stream.concat(listaProcessiOrganization.stream(), listaProcessiGlobal.stream())
                    .collect(Collectors.toList());
            listaFormPrincipali  = Stream.concat(listaFormPrincipaliOrganization.stream(), listaFormPrincipaliGlobal.stream())
                    .collect(Collectors.toList());
            listaFormIntegrativi = Stream.concat(listaFormIntegrativiOrganization.stream(), listaFormIntegrativiGlobal.stream())
                    .collect(Collectors.toList());

            listaTipologiaBando = tipologiaBandoLocalService.findByGroupIdAndDominio(siteGroupId, Dominio.BANDI.name());
            // listaStatoDomanda = statoDomandaLocalService.findByGroupId(siteGroupId);
            listaStatoDomandaAutocomplete = statoDomandaLocalService.findByGroupId(siteGroupId);

            listaArticoliCatalogoBandi = gestioneBandiMiddlewareService.getListaArticleIdDisponibili(themeDisplay.getSiteGroup()
                    .getOrganizationId(), idBando, GestioneBandiFrontendPortletKeys.STRUCTURE_NAME_SCHEDA_BANDO);

            listaArticoliFaqBandi = gestioneBandiMiddlewareService.getListaArticleIdDisponibili(themeDisplay.getSiteGroup()
                    .getOrganizationId(), idBando, GestioneBandiFrontendPortletKeys.STRUCTURE_NAME_FAQ);

            try{
                pagineDisponibili = gestioneBandiMiddlewareService.getListaPagineUtilizzabili(themeDisplay.getSiteGroup()
                        .getOrganizationId(), idBando, themeDisplay.getCompanyId());
            }
            catch(NoSuchLayoutException e){
                _log.error("Impossibile recuperare le pagine utilizzabili");
            }

            if(Validator.isNotNull(organizationId)){

                _log.debug("organizationId" + themeDisplay.getSiteGroup().getOrganizationId());
                // Organization organization
                // =organizationLocalService.getOrganization(organizationId);
                // renderRequest.setAttribute(GestioneEntiPortletKeys.ORGANIZZAZIONE,
                // organization);

                List<Organization> organizations = organizationLocalService.getOrganizations(themeDisplay.getCompanyId(), themeDisplay.getSiteGroup()
                        .getOrganizationId());
                List<OrganizationDTO> listaOrganizationsDto = new ArrayList<>();
                for(Organization org : organizations){
                    OrganizationDTO organizationDTO = new OrganizationDTO();

                    organizationDTO.setOrganizationId(org.getOrganizationId());
                    organizationDTO.setName(org.getName().replaceAll("'", "&apos;"));
                    listaOrganizationsDto.add(organizationDTO);
                }
                renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_SOTTO_ORGANIZZAZIONI, organizations);
                renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_SOTTO_ORGANIZZAZIONI_DTO, listaOrganizationsDto);
            }

        }
        catch(Exception e){
            _log.error(e.getMessage(), e);
        }

        if(idBando > 0){
            auditService.saveLog(renderRequest, "Visualizza bando " + idBando, EsitoOperazione.OK, null);

            try{
                bando                     = bandoLocalService.getBando(idBando);
                listaFormIntegrativiBando = gestioneBandiMiddlewareService.getFormIntegrativiBando(idBando);
                formPrincipale            = gestioneBandiMiddlewareService.getFormPrincipaleBando(idBando);

                listaRequisitoDomandaBando = requisitoDomandaBandoLocalService.getRequisitoDomandaBandoByBandoId(idBando);

                for(RequisitoDomandaBando req : listaRequisitoDomandaBando){
                    listaValoreRequisitoDomanda = valoreRequisitoDomandaLocalService.getValoreRequisitoDomandaByRequisitoDomandaBandoId(req.getRequisitoDomandaBandoId());

                    listaValoreRequisitoDomanda.stream()
                            .forEach(valoreRequisitoDomanda ->
                                    valoreRequisitoDomanda.setValoreRiferimento(valoreRequisitoDomanda.getValoreRiferimento().replace("$.", ""))
                            );

                    mapValoreRequisitoDomanda.put(req.getRequisitoDomandaBandoId(), listaValoreRequisitoDomanda);
                }

                String codiceCriterioPunteggioTotale = bando.getCodice() + "_" + GestioneBandiCommonConstants.CODICE_CRIT_PUNTEGGIO_TOT;

                List<String> tipoFormList = TipoFormEnum.getTipoFormEsecuzione().stream().map(Enum::name).collect(Collectors.toList());
                List<BandoForm> listaIntegrativiEsecuzione = bandoFormLocalService.getListaBandoFormBandoAndTipoFormAndFormIdNotIn(idBando, tipoFormList, null);

                List<BandoForm> listaIntegrativi = new ArrayList<>();
                List<BandoForm> listaIntegrativiNonMod = bandoFormLocalService.getListaBandoFormBandoAndType(idBando, "");
                List<String> tipoFormIntegrazioneList = new ArrayList<>();
                tipoFormIntegrazioneList.add(TipoFormEnum.INTEGRAZIONE.name());
                tipoFormIntegrazioneList.add(TipoFormEnum.INTEGRAZIONE_OPERATORE.name());
                tipoFormIntegrazioneList.add(TipoFormEnum.INTEGRAZIONE_OPERATORE_ESECUZIONE.name());
                tipoFormIntegrazioneList.add(TipoFormEnum.INTEGRAZIONE_FRONTEND.name());
                tipoFormIntegrazioneList.add(TipoFormEnum.ESECUZIONE_INTEGRAZIONE.name());
                tipoFormIntegrazioneList.add(TipoFormEnum.ESECUZIONE_INTEGRAZIONE_DISCIPLINARE.name());
                tipoFormIntegrazioneList.add(TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name());
                tipoFormIntegrazioneList.add(TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name());
                List<BandoForm> listaIntegrativiIntegrazioneNonMod = bandoFormLocalService.getListaBandoFormBandoAndTipoFormAndFormIdNotIn(idBando, tipoFormIntegrazioneList, null);
                if(Validator.isNotNull(listaIntegrativiNonMod) && !listaIntegrativiNonMod.isEmpty()){
                    listaIntegrativi.addAll(listaIntegrativiNonMod);
                }
                if(Validator.isNotNull(listaIntegrativiIntegrazioneNonMod) && !listaIntegrativiIntegrazioneNonMod.isEmpty()){
                    listaIntegrativi.addAll(listaIntegrativiIntegrazioneNonMod);
                }

                List<BandoForm> listaIntegrativiAnnullamento = bandoFormLocalService.getListaBandoFormBandoAndType(idBando, TipoFormEnum.ANNULLAMENTO.name());
                _log.debug("listaIntegrativiEsecuzione in fase render : " + listaIntegrativiEsecuzione);
                _log.debug("listaIntegrativi in fase render : " + listaIntegrativi);
                _log.debug("listaIntegrativiAnnullamento in fase render : " + listaIntegrativiAnnullamento);
                for(BandoForm bandoForm : listaIntegrativi){
                    long idForm = bandoForm.getFormId();
                    Form form   = formLocalService.getForm(idForm);
                    _log.debug("idForm:" + idForm);
                    if(form.getPrincipale()){
                        continue;
                    }
                    form.setJson("");
                    listaFormIntegrativiSelected.add(String.valueOf(form.getFormId()));
                    // listaFormIntegrativiSelected.add(form);
                }
                for(BandoForm bandoForm : listaIntegrativiEsecuzione){
                    long idForm = bandoForm.getFormId();
                    Form form   = formLocalService.getForm(idForm);
                    _log.debug("idForm:" + idForm);
                    if(form.getPrincipale()){
                        continue;
                    }
                    form.setJson("");

                    listaFormIntegrativiEsecuzioneSelected.add(String.valueOf(form.getFormId()));
                    // listaFormIntegrativiEsecuzioneSelected.add(form);
                }
                for(BandoForm bandoForm : listaIntegrativiAnnullamento){
                    long idForm = bandoForm.getFormId();
                    Form form   = formLocalService.getForm(idForm);
                    _log.debug("idForm:" + idForm);
                    if(form.getPrincipale()){
                        continue;
                    }
                    form.setJson("");

                    listaFormIntegrativiAnnullamentoSelected.add(String.valueOf(form.getFormId()));
                    // listaFormIntegrativiEsecuzioneSelected.add(form);
                }

                listaContributoBando     = contributoBandoLocalService.getContributoBandoByBandoId(idBando);

                List<CriterioValutazione> listaCriterioValutazioneDaOrdinare = criterioValutazioneLocalService.getCriterioValutazioneByBandoIdAndNotCodice(idBando, codiceCriterioPunteggioTotale);
                if(listaCriterioValutazioneDaOrdinare!=null){
                    listaCriterioValutazione = listaCriterioValutazioneDaOrdinare.stream().sorted((o1, o2) -> Integer.compare(o1.getOrdine(), o2.getOrdine())).collect(Collectors.toList());

                    listaCriterioValutazione.forEach(criterio -> {
                        criterio.setSogliaMinima(criterio.getSogliaMinima().setScale(2, RoundingMode.HALF_UP));
                        criterio.setPunteggioMassimo(criterio.getPunteggioMassimo().setScale(2, RoundingMode.HALF_UP));
                        criterio.setPunteggioMinimo(criterio.getPunteggioMinimo().setScale(2, RoundingMode.HALF_UP));
                    });
                }

                listaTermineBando        = termineBandoLocalService.getTermineBandoByBandoId(idBando);
                listaStatoDomandaBando   = statoDomandaBandoLocalService.getStatoDomandaBandoByBandoId(idBando);
                listaSottoOrganizzazione = sottoOrganizzazioneLocalService.getListSottoOrganizzazioneByBandoId(idBando);
                for(StatoDomandaBando statoDomandaBando : listaStatoDomandaBando){
                    StatoDomanda sd = statoDomandaLocalService.getStatoDomanda(statoDomandaBando.getStatoId());
                    listaStatoDomanda.add(sd);
                    StatoDomandaBandoDTO statoDTO = new StatoDomandaBandoDTO();
                    statoDTO.setCodice(sd.getCodice());
                    statoDTO.setDescrizione(statoDomandaBando.getDescrizione());
                    statoDTO.setAbilitaRichiedente(statoDomandaBando.getAbilitaRichiedente());
                    statoDTO.setStatoDomandaId(sd.getStatoDomandaId());
                    listaDomandaStatoDTO.add(statoDTO);
                }

                _log.debug("listaIntegrativiEsecuzione:" + listaIntegrativiEsecuzione);
                _log.debug("listaIntegrativi:" + listaIntegrativi);
                _log.debug("listaContributoBando:" + listaContributoBando);
                _log.debug("listaCriterioValutazione:" + listaCriterioValutazione);
                _log.debug("listaTermineBando: " + listaTermineBando);
                _log.debug("listaSottoOrganizzazione: " + listaSottoOrganizzazione);

                if(Validator.isNotNull(listaFormIntegrativiSelected)){

                    _log.debug("listaFormIntegrativiSelected:" + listaFormIntegrativiSelected);

                    _log.debug(GestioneBandiFrontendPortletKeys.FORM_BANDI_INTEGRATIVI + " " + listaFormIntegrativiSelected);
                    renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.FORM_BANDI_INTEGRATIVI, listaFormIntegrativiSelected);
                }
                else{
                    renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.FORM_BANDI_INTEGRATIVI, GestioneBandiFrontendPortletKeys.LISTA_VUOTA);
                }

                if(Validator.isNotNull(listaFormIntegrativiEsecuzioneSelected)){

