    private String normalizeTemplateFileName(String originalFileName, String codiceTemplate) {
        if (Validator.isNull(originalFileName) || Validator.isNull(codiceTemplate)) {
            return originalFileName;
        }

        int lastDotIndex = originalFileName.lastIndexOf('.');
        if (lastDotIndex == -1) {
            return originalFileName;
        }

        String fileNameWithoutExt = originalFileName.substring(0, lastDotIndex);
        String extension = originalFileName.substring(lastDotIndex); // includes the dot

        String suffix = "_" + codiceTemplate.toLowerCase();

        if (fileNameWithoutExt.toLowerCase().endsWith(suffix.toLowerCase())) {
            return originalFileName;
        }

        String[] possibleSuffixes = {
            "_istanza", "_richiesta_soccorso_istruttorio", "_istanza_soccorso_istruttorio",
            "_istanza_annullamento", "_disciplinare", "_prima_domanda_anticipo",
            "_seconda_domanda_anticipo", "_esito_domanda"
        };

        for (String possibleSuffix : possibleSuffixes) {
            if (fileNameWithoutExt.toLowerCase().endsWith(possibleSuffix.toLowerCase())) {
                fileNameWithoutExt = fileNameWithoutExt.substring(0, fileNameWithoutExt.length() - possibleSuffix.length());
                break;
            }
        }

        return fileNameWithoutExt + suffix + extension;
    }

    /**
     * Verifica che la sezione template Jasper indicata sia configurabile/salvabile.
     * A differenza del template nativo (che dispone di un default) il template Jasper non ha un
     * default, quindi <b>ogni riga</b> deve avere un allegato: un file caricato in questa richiesta
     * oppure un template gi&agrave; persistito (reportId &gt; 0). Un template Jasper gi&agrave; salvato
     * espone sempre il proprio templatePdfId (PK &gt; 0) nella JSP, quindi i bandi esistenti restano
     * validi senza dover ricaricare il file (retrocompatibilit&agrave;); l'apertura del bando non passa
     * comunque da questa validazione, che &egrave; attiva solo in salvataggio.
     *
     * @return true se la configurazione Jasper &egrave; valida/salvabile, false se va bloccata
     */
    private boolean templateJasperConfigurabile(ActionRequest actionRequest, UploadPortletRequest uploadPortletRequest, String suffisso, String rowIndexes) {
        if (Validator.isNull(rowIndexes)) {
            return false;
        }

        long count = Long.valueOf(rowIndexes);
        if (count <= 0) {
            return false;
        }

        for (int i = 0; i < count; i++) {
            long reportId = ParamUtil.getLong(actionRequest, "idAllegatoJasper" + suffisso + i);
            File file = uploadPortletRequest.getFile("jasperReportFile" + suffisso + i);
            String nomeFile = uploadPortletRequest.getFileName("jasperReportFile" + suffisso + i);
            boolean fileFornito = Validator.isNotNull(file) && Validator.isNotNull(nomeFile);
            if (!fileFornito && reportId <= 0) {
                return false;
            }
        }

        return true;
    }

