            if(valore != null && !"".equals(valore)){
                // Line 3776-3785: Create or update ValoreDatoBando
                ValoreDatoBando valoreDatoBando = this.getValoriDatoBando(
                        datoBando.getDatoBandoId(),
                        valoreId,
                        valore.trim(),
                        idBando,
                        userFullName,
                        userId,
                        siteGroupId,
                        companyId
                );

                if(valoreDatoBando != null){
                    // Line 3788-3789: Add to lists
                    listaIdValoriDatiBando.add(valoreDatoBando.getValoreDatoBandoId());
                    listaValoriDatiBando.add(valoreDatoBando);
